179	// TestRevokeAuthzUsedSaveFailure 覆盖：授权人撤销已使用授权的
180	// ErrAuthorizationUsed 拒绝在拒绝结果自身落盘失败时，同样返回实际保存错误
181	// 与空结果；已使用终态、使用关联与授权变更记录保持操作前内容，藏品持有
182	// 不变。保存恢复后原请求重提重新保存该拒绝（首次不标回放），再次提交才
183	// 回放。
184	func TestRevokeAuthzUsedSaveFailure(t *testing.T) {
185		r := mustCreate(t, tempDir(t))
186		setupUsedAuthzWorld(t, r)
187		req := revokeAuthzSaveReq("alice", "a2", "rv-used")
188	
189		blockBatchSave(t, r)
190		res, err := r.RevokeAuthorization(req)
191		assertRevokeAuthzSaveFailureEmpty(t, res, err)
192		assertRevokeRequestFree(t, r, req)
193		// 已使用终态及其使用关联保持操作前内容。
194		a, err := r.GetAuthorization("a2")
195		if err != nil || a.Status != AuthUsed || a.UsedTxSeq != 2 {
196			t.Fatalf("未保存的拒绝不应改变已使用授权: %+v, %v", a, err)
197		}
198		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 ||
199			evs[2].Kind != "use" || evs[2].AuthID != "a2" {
200			t.Fatalf("授权变更记录应保持操作前的 3 条: %+v", evs)
201		}
202		assertHoldingUnchanged(t, r, "i1", "carol", 2, 2)
203	
204		// 保存仍被阻断时再次提交：仍失败在保存上，不能回放未保存的拒绝。
205		res, err = r.RevokeAuthorization(req)
206		assertRevokeAuthzSaveFailureEmpty(t, res, err)
207		assertRevokeRequestFree(t, r, req)
208	
209		restoreBatchSave(t, r)
210		// 重提：先成功保存此次拒绝，再返回 ErrAuthorizationUsed，首次不标回放，
211		// 结果带原授权编号与业务错误、状态为空。
212		res, err = r.RevokeAuthorization(req)
213		if !errors.Is(err, ErrAuthorizationUsed) {
214			t.Fatalf("重提应在保存成功后返回 ErrAuthorizationUsed: %v", err)
215		}
216		if res.Replayed || res.AuthID != "a2" || !errors.Is(res.Err, ErrAuthorizationUsed) ||
217			res.Status != "" {
218			t.Fatalf("已使用拒绝的重提结果异常: %+v", res)
219		}
220		assertRevokeRequestSaved(t, r, req)
221		a, _ = r.GetAuthorization("a2")
222		if a.Status != AuthUsed || a.UsedTxSeq != 2 {
223			t.Fatalf("已使用拒绝不应改变授权: %+v", a)
224		}
225		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 {
226			t.Fatalf("已使用拒绝不应新增授权变更记录: %+v", evs)
227		}
228	
229		// 拒绝已保存：相同内容重提回放原拒绝。
230		res, err = r.RevokeAuthorization(req)
231		if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed ||
232			res.AuthID != "a2" || !errors.Is(res.Err, ErrAuthorizationUsed) {
233			t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
234		}
235	}
