250		}
251		if !creator.Active {
252			return fmt.Errorf("%w: 创建账户 %s", ErrAccountInactive, creatorID)
253		}
254		if _, ok := r.state.Series[id]; ok {
255			return fmt.Errorf("%w: 系列 %s", ErrAlreadyExists, id)
256		}
257		r.state.Series[id] = series{ID: id, CreatorID: creatorID, Metadata: metadata}
258		return r.commit()
