496	
497	func transferParamsSig(req TransferRequest) string {
498		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
499		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
500		// 冲突拒绝。
501		b, _ := json.Marshal(struct {
502			Kind          string `json:"kind"`
503			ItemID        string `json:"item_id"`
504			ExpectedOwner string `json:"expected_owner"`
505			ExpectedVer   int64  `json:"expected_version"`
506			ToID          string `json:"to_id"`
507			Price         int64  `json:"price,omitempty"`
508			Reason        string `json:"reason"`
509		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
510		return string(b)
511	}
512	
513	// transferOutcome 是一笔成功转让落盘后的执行结果，供各转让入口组装
514	// 各自的返回结构与请求记录。
515	type transferOutcome struct {
516		seq     int64      // 转让历史序号
517		fromID  string     // 转让前持有人
518		fromVer int64      // 转让前持有版本
519		royalty royaltyRec // 版税应付记录（含价款、明细与余款）
520	}
521	
522	// toVer 是转让后的持有版本。
523	func (o transferOutcome) toVer() int64 { return o.fromVer + 1 }
524	
525	// applyTransfer 完成一笔成功转让的全部状态变化：持有版本加一并换主、
526	// 追加转让历史、按所属系列的版税规则快照计算应付明细与归转让前持有人
527	// 的余款。直接转让、授权代转与整批转让共用这一段逻辑，保证同一笔转让
528	// 的持有、历史与金额记录始终一致；authID 为空表示直接转让。调用方负责
529	// 前置校验、请求结果登记与落盘，调用时必须持有锁且校验已通过。
530	func (r *Registry) applyTransfer(itemID, toID, operator, reason, requestID, authID string, price int64) transferOutcome {
531		h := r.state.Holdings[itemID]
532		seq := r.state.NextSeq + 1
533		r.state.NextSeq = seq
534		from := h.OwnerID
535		fromVer := h.Version
536		h.OwnerID = toID
537		h.Version = fromVer + 1
538		r.state.Holdings[itemID] = h
539		r.state.History = append(r.state.History, historyEntry{
540			Seq: seq, Kind: "transfer", ItemID: itemID, Operator: operator,
541			Reason: reason, RequestID: requestID,
542			FromID: from, ToID: toID, FromVersion: fromVer, ToVersion: fromVer + 1,
543			AuthID: authID,
544		})
545		// 版税按所属系列的规则快照计算；余款归转让前持有人。
546		it := r.state.Items[itemID]
547		royalty := newRoyaltyRec(seq, itemID, it.SeriesID, price,
548			r.state.Series[it.SeriesID].Royalty, from)
549		r.state.Royalties[seq] = royalty
550		return transferOutcome{seq: seq, fromID: from, fromVer: fromVer, royalty: royalty}
551	}
552	
553	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
554	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
555	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
556	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
557	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
558	// 请求重复提交（即使藏品后来已易手）返回首次结果。
559	//
560	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
561	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
562	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
563	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
564	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
565	// 正常转出。
566	//
567	// 成功转让同样以保存完成为准：持有换人、版本加一、转让历史、版税应付、
568	// 历史序号与请求结果都尚未写入原登记册而保存失败（如数据位置暂时无法
569	// 写入）时，返回实际保存错误而非转让成功，结果为空（不携带藏品编号、前后
570	// 持有人、版本、历史序号、价款、应付或余款，业务错误为空，不标回放）。
571	// 即使失败后原数据暂时无法读取、状态未能按磁盘重建，这笔转让也必须从当前
572	// 仍打开的登记册中整体撤销：藏品仍属于提交前的持有人、版本不增加、持有
573	// 列表与藏品历史保持原状、版税查询没有本次计算记录、收款账户不多出应付，
574	// 请求号与历史序号都不被消耗；失败前已存在的成功转让、应付与其他藏品记录
575	// 原样保留，随后另一次无关操作成功保存也不会把这笔未保存的转让一并写入。
576	// 读写条件恢复后用原操作者、请求号、原因和全部转让参数重新提交，按当时的
577	// 持有与账户状态重新判断：条件仍满足时正常完成一次转让（版本只增加一次、
578	// 序号紧接已有历史、不标回放），此后再次提交相同内容才回放这一笔已保存的
579	// 结果；恢复期间藏品已被另一笔合法转让转出的，原请求按现有版本冲突规则
580	// 拒绝，不能回放先前未保存的成功。
581	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
582		if err := req.validatePresent(); err != nil {
583			return TransferResult{}, err
584		}
585		r.mu.Lock()
586		defer r.mu.Unlock()
587		if err := r.checkOpen(); err != nil {
588			return TransferResult{}, err
589		}
590	
591		key := requestKey(req.Operator, req.RequestID)
592		sig := transferParamsSig(req)
593		if prev, ok := r.state.Requests[key]; ok {
594			return r.replayTransfer(prev, sig)
595		}
596	
597		bizErr := r.checkTransfer(req)
598		if bizErr != nil {
599			if !isValidationErr(bizErr) {
600				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
601				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
602				r.state.Requests[key] = request{
603					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
604					Params: sig, Rejected: true, Reason: errCode(bizErr),
605					ItemID: req.ItemID,
606				}
607				if err := r.commit(); err != nil {
608					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
609					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
610					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
611					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
612					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
613					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
614					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
615					// 实际写入错误。
616					delete(r.state.Requests, key)
617					return TransferResult{}, err
618				}
619			}
620			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
621			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
622		}
623	
624		// 回滚基点：本次成功转让的全部改动（持有换人、版本加一、历史、版税
625		// 应付、历史序号、请求结果）都必须以一次保存完成为准。记录改动前的
626		// 持有、历史长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘
627		// 重建时据此整体撤销，否则后续任何一次成功保存都会把这笔未保存的转让
628		// 带进登记册，造成"已换人、可回放"的幻影交易。
629		prevHolding := r.state.Holdings[req.ItemID]
630		prevNextSeq := r.state.NextSeq
631		prevHistLen := len(r.state.History)
632	
633		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
634		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
635		r.state.Requests[key] = request{
636			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
637			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
638			Version: out.toVer(), TxSeq: out.seq,
639		}
640		if err := r.commit(); err != nil {
641			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
642			// 旧状态整体撤销（持有未换人、无本次历史与应付、请求记录不存在、
643			// 序号未消耗），无需再动；磁盘暂时不可读、状态未能重建时本次改动
644			// 仍在，据此把这笔未保存的转让全部撤销，让当前已打开的登记册回到
645			// 提交前状态，也不被随后另一次成功保存带入。返回空结果：无藏品
646			// 编号、无前后持有人、无版本、无历史序号、无价款/应付/余款、不标
647			// 回放、结果中业务错误为空，error 保留实际写入错误。
648			if _, pending := r.state.Requests[key]; pending {
649				delete(r.state.Requests, key)
650				delete(r.state.Royalties, out.seq)
651				r.state.History = r.state.History[:prevHistLen]
652				r.state.Holdings[req.ItemID] = prevHolding
653				r.state.NextSeq = prevNextSeq
654			}
655			return TransferResult{}, err
656		}
657		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
658			Version: out.toVer(), TxSeq: out.seq,
659			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
660			Remainder: out.royalty.Remainder}, nil
661	}
662	
663	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
664	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
665	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
666	// 于持有信息不符。
667	func (r *Registry) checkTransfer(req TransferRequest) error {
668		return r.checkSingleTransferEligibility(directTransferEligibility{
669			itemID:        req.ItemID,
670			operator:      req.Operator,
671			toID:          req.ToID,
672			expectedOwner: req.ExpectedOwner,
673			expectedVer:   req.ExpectedVer,
674		})
675	}
676	
677	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
678		if prev.Kind != "transfer" || prev.Params != sig {
679			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
680				ErrRequestConflict, prev.Operator, prev.RequestID)
681		}
682		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
683			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
684		if prev.Rejected {
685			res.Err = codeErr(prev.Reason)
686			return res, res.Err
687		}
688		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
689		// 价款与应付明细，不重复计入。
690		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
691		return res, nil
692	}
693	
694	// ---- 限时一次性代转授权 ----
695	
696	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
697	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
698	func authzCurrentStatus(a authzRec, now time.Time) string {
699		switch a.Status {
700		case "revoked":
701			return AuthRevoked
702		case "used":
703			return AuthUsed
704		}
705		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
706			return AuthExpired
707		}
708		return AuthActive
709	}
710	
711	func (req CreateAuthorizationRequest) validatePresent() error {
712		missing := []string{}
713		if strings.TrimSpace(req.Operator) == "" {
714			missing = append(missing, "operator")
715		}
716		if strings.TrimSpace(req.Reason) == "" {
717			missing = append(missing, "reason")
718		}
719		if strings.TrimSpace(req.RequestID) == "" {
720			missing = append(missing, "request_id")
721		}
722		if strings.TrimSpace(req.AuthID) == "" {
723			missing = append(missing, "auth_id")
724		}
725		if strings.TrimSpace(req.ItemID) == "" {
726			missing = append(missing, "item_id")
727		}
728		if strings.TrimSpace(req.TrusteeID) == "" {
729			missing = append(missing, "trustee_id")
730		}
731		if strings.TrimSpace(req.ToID) == "" {
732			missing = append(missing, "to_id")
733		}
734		if strings.TrimSpace(req.ExpectedOwner) == "" {
735			missing = append(missing, "expected_owner")
736		}
737		if req.ExpectedVer <= 0 {
738			missing = append(missing, "expected_version")
739		}
740		if req.ExpiresAt.IsZero() {
741			missing = append(missing, "expires_at")
742		}
743		if len(missing) > 0 {
744			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
745		}
746		if req.Price < 0 {
747			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
748		}
749		return nil
750	}
751	
752	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
753		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
754		// 仍可回放；改价则按请求号冲突拒绝。
755		b, _ := json.Marshal(struct {
756			Kind          string `json:"kind"`
757			AuthID        string `json:"auth_id"`
758			ItemID        string `json:"item_id"`
759			TrusteeID     string `json:"trustee_id"`
760			ToID          string `json:"to_id"`
761			ExpectedOwner string `json:"expected_owner"`
762			ExpectedVer   int64  `json:"expected_version"`
763			ExpiresAt     string `json:"expires_at"`
764			Price         int64  `json:"price,omitempty"`
765			Reason        string `json:"reason"`
766		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
767			req.ExpectedOwner, req.ExpectedVer,
768			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
769		return string(b)
770	}
771	
772	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
773	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
774	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
775	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
776	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
777	//
778	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
779	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
780	// 参数错误与引用不存在不占用请求号。
781	//
782	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
783	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
784	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
785	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
786	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
787	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
788	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
789	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
790	// 错误（首次重提不标回放），状态已满足请求则正常创建。
791	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
792		if err := req.validatePresent(); err != nil {
793			return CreateAuthorizationResult{}, err
794		}
795		r.mu.Lock()
796		defer r.mu.Unlock()
797		if err := r.checkOpen(); err != nil {
798			return CreateAuthorizationResult{}, err
799		}
800	
801		now := r.now()
802		key := requestKey(req.Operator, req.RequestID)
803		sig := createAuthzParamsSig(req)
804		if prev, ok := r.state.Requests[key]; ok {
805			return r.replayCreateAuthz(prev, sig)
806		}
807	
808		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
809			if !isValidationErr(bizErr) {
810				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
811				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
812				r.state.Requests[key] = request{
813					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
814					Params: sig, Rejected: true, Reason: errCode(bizErr),
815					AuthID: req.AuthID, ItemID: req.ItemID,
816				}
817				if err := r.commit(); err != nil {
818					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
819					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
820					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
821					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
822					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
823					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
824					// 为零、不标回放、结果中业务错误为空，error 保留实际
825					// 写入错误。
826					delete(r.state.Requests, key)
827					return CreateAuthorizationResult{}, err
828				}
829			}
830			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
831		}
832	
833		h := r.state.Holdings[req.ItemID]
834		a := authzRec{
835			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
836			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
837			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
838		}
839		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
840		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
841		// 一次成功保存都会把这份未保存的授权带进登记册。
842		prevAuthSeq := r.state.NextAuthSeq
843		prevEvents := len(r.state.AuthEvents)
844		r.state.Authzs[req.AuthID] = a
845		authSeq := prevAuthSeq + 1
846		r.state.NextAuthSeq = authSeq
847		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
848			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
849			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
850			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
851		})
852		r.state.Requests[key] = request{
853			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
854			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
855		}
856		if err := r.commit(); err != nil {
857			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
858			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
859			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
860			if _, ok := r.state.Requests[key]; ok {
861				delete(r.state.Requests, key)
862				delete(r.state.Authzs, req.AuthID)
863				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
864				r.state.NextAuthSeq = prevAuthSeq
865			}
866			return CreateAuthorizationResult{}, err
867		}
868		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
869	}
870	
871	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
872		h, ok := r.state.Holdings[req.ItemID]
873		if !ok {
874			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
875				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
876			}
877			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
878		}
879		op, ok := r.state.Accounts[req.Operator]
880		if !ok {
881			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
882		}
883		trustee, ok := r.state.Accounts[req.TrusteeID]
884		if !ok {
885			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
886		}
887		to, ok := r.state.Accounts[req.ToID]
888		if !ok {
889			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
890		}
891		if req.TrusteeID == req.Operator {
892			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
893		}
894		if req.ToID == req.Operator {
895			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
896		}
897		if !op.Active {
898			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
899		}
900		if !trustee.Active {
901			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
902		}
903		if !to.Active {
904			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
905		}
906		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
907		if _, exists := r.state.Authzs[req.AuthID]; exists {
908			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
909		}
910		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
911		if !req.ExpiresAt.After(now) {
912			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
913				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
914		}
915		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
916			req.Operator != h.OwnerID {
917			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
918				ErrConflict, req.ItemID, h.OwnerID, h.Version)
919		}
920		return nil
921	}
922	
923	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
924		if prev.Kind != "auth_create" || prev.Params != sig {
925			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
926				ErrRequestConflict, prev.Operator, prev.RequestID)
927		}
928		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
929			Status: AuthActive, Replayed: true}
930		if prev.Rejected {
931			res.Err = codeErr(prev.Reason)
932			return res, res.Err
933		}
934		return res, nil
935	}
936	
937	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
938		b, _ := json.Marshal(struct {
939			Kind   string `json:"kind"`
940			AuthID string `json:"auth_id"`
941			Reason string `json:"reason"`
942		}{"auth_revoke", req.AuthID, req.Reason})
943		return string(b)
944	}
945	
946	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
947	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
948	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
949	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
950	// revoked）。请求号语义与其他操作一致。
951	//
952	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
953	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
954	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
955	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
956	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
957	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
958	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
959	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
960	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
961	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
962	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
963	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
964	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
965	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
966		missing := []string{}
967		if strings.TrimSpace(req.Operator) == "" {
968			missing = append(missing, "operator")
969		}
970		if strings.TrimSpace(req.Reason) == "" {
971			missing = append(missing, "reason")
972		}
973		if strings.TrimSpace(req.RequestID) == "" {
974			missing = append(missing, "request_id")
975		}
976		if strings.TrimSpace(req.AuthID) == "" {
977			missing = append(missing, "auth_id")
978		}
979		if len(missing) > 0 {
980			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
981				ErrInvalidArgument, strings.Join(missing, ", "))
982		}
983		r.mu.Lock()
984		defer r.mu.Unlock()
985		if err := r.checkOpen(); err != nil {
986			return RevokeAuthorizationResult{}, err
987		}
988	
989		now := r.now()
990		key := requestKey(req.Operator, req.RequestID)
991		sig := revokeAuthzParamsSig(req)
992		if prev, ok := r.state.Requests[key]; ok {
993			return r.replayRevokeAuthz(prev, sig)
994		}
995	
996		a, ok := r.state.Authzs[req.AuthID]
997		if !ok {
998			// 引用不存在不占用请求号。
999			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1000			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
1001		}
1002		if a.GranterID != req.Operator {
1003			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
1004				ErrForbidden, a.GranterID, req.AuthID)
1005			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1006				return RevokeAuthorizationResult{}, err
1007			}
1008			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1009		}
1010		switch authzCurrentStatus(a, now) {
1011		case AuthUsed:
1012			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
1013			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1014				return RevokeAuthorizationResult{}, err
1015			}
1016			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1017		case AuthRevoked:
1018			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
1019			// 相同请求重放回放同一结果。
1020			r.state.Requests[key] = request{
1021				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1022				Params: sig, AuthID: req.AuthID,
1023			}
1024			if err := r.commit(); err != nil {
1025				return RevokeAuthorizationResult{}, err
1026			}
1027			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1028		}
1029	
1030		from := AuthActive
1031		if authzCurrentStatus(a, now) == AuthExpired {
1032			from = AuthExpired
1033		}
1034		a.Status = "revoked"
1035		a.RevokedAt = now
1036		r.state.Authzs[req.AuthID] = a
1037		authSeq := r.state.NextAuthSeq + 1
1038		r.state.NextAuthSeq = authSeq
1039		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1040			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
1041			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1042			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
1043		})
1044		r.state.Requests[key] = request{
1045			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1046			Params: sig, AuthID: req.AuthID,
1047		}
1048		if err := r.commit(); err != nil {
1049			return RevokeAuthorizationResult{}, err
1050		}
1051		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1052	}
1053	
1054	// recordRevokeRejection 登记撤销授权的状态类业务拒绝（非授权人的
1055	// ErrForbidden、授权人撤销已使用授权的 ErrAuthorizationUsed）并落盘。
1056	// 拒绝结果以保存完成为准：落盘失败时显式撤销尚未保存的请求号占用并返回
1057	// 实际保存错误，调用方必须返回空结果与该错误，不能只返回业务拒绝让调用者
1058	// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
1059	func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
1060		r.state.Requests[key] = request{
1061			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1062			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1063		}
1064		if err := r.commit(); err != nil {
1065			// commit 失败时已尝试按磁盘内容重建状态，请求记录随之撤销；此处再
1066			// 删一次以覆盖磁盘暂时不可读、状态未能重建的情形——未保存的拒绝
1067			// 不能留在当前已打开的登记册中，也不能随随后另一次正常操作被保存。
1068			delete(r.state.Requests, key)
1069			return err
1070		}
1071		return nil
1072	}
1073	
1074	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
1075		if prev.Kind != "auth_revoke" || prev.Params != sig {
1076			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1077				ErrRequestConflict, prev.Operator, prev.RequestID)
1078		}
1079		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
1080		if prev.Rejected {
1081			res.Err = codeErr(prev.Reason)
1082			res.Status = ""
1083			return res, res.Err
1084		}
1085		return res, nil
1086	}
