1088	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1089		b, _ := json.Marshal(struct {
1090			Kind   string `json:"kind"`
1091			AuthID string `json:"auth_id"`
1092			Reason string `json:"reason"`
1093		}{"proxy_transfer", req.AuthID, req.Reason})
1094		return string(b)
1095	}
1096	
1097	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1098	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1099	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1100	// 操作者记为实际受托账户并可通过授权编号追溯。
1101	//
1102	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1103	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1104	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1105	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1106	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1107	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1108	//
1109	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1110	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1111	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1112	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1113	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1114	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1115	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1116	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1117	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1118	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1119	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1120	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1121	// 或引用不存在沿用原错误且不占用请求号。
1122	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1123		missing := []string{}
1124		if strings.TrimSpace(req.Operator) == "" {
1125			missing = append(missing, "operator")
1126		}
1127		if strings.TrimSpace(req.Reason) == "" {
1128			missing = append(missing, "reason")
1129		}
1130		if strings.TrimSpace(req.RequestID) == "" {
1131			missing = append(missing, "request_id")
1132		}
1133		if strings.TrimSpace(req.AuthID) == "" {
1134			missing = append(missing, "auth_id")
1135		}
1136		if len(missing) > 0 {
1137			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1138				ErrInvalidArgument, strings.Join(missing, ", "))
1139		}
1140		r.mu.Lock()
1141		defer r.mu.Unlock()
1142		if err := r.checkOpen(); err != nil {
1143			return ProxyTransferResult{}, err
1144		}
1145	
1146		now := r.now()
1147		key := requestKey(req.Operator, req.RequestID)
1148		sig := proxyTransferParamsSig(req)
1149		if prev, ok := r.state.Requests[key]; ok {
1150			return r.replayProxyTransfer(prev, sig)
1151		}
1152	
1153		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1154			if !isValidationErr(bizErr) {
1155				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1156				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1157				r.state.Requests[key] = request{
1158					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1159					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1160				}
1161				if err := r.commit(); err != nil {
1162					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1163					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1164					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1165					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1166					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1167					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1168					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1169					// 回放、结果中业务错误为空，error 保留实际写入错误。
1170					delete(r.state.Requests, key)
1171					return ProxyTransferResult{}, err
1172				}
1173			}
1174			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1175			// 授权状态或授权变更记录。
1176			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1177		}
1178	
1179		a := r.state.Authzs[req.AuthID]
1180		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1181		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1182		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1183		// 追溯。
1184		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1185		a.Status = "used"
1186		a.UsedTxSeq = out.seq
1187		a.UsedAt = now
1188		r.state.Authzs[a.ID] = a
1189		authSeq := r.state.NextAuthSeq + 1
1190		r.state.NextAuthSeq = authSeq
1191		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1192			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1193			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1194			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1195		})
1196		r.state.Requests[key] = request{
1197			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1198			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1199			Version: out.toVer(), TxSeq: out.seq,
1200		}
1201		if err := r.commit(); err != nil {
1202			return ProxyTransferResult{}, err
1203		}
1204		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1205			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1206			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1207			Remainder: out.royalty.Remainder}, nil
1208	}
1209	
1210	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1211		a, ok := r.state.Authzs[req.AuthID]
1212		if !ok {
1213			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1214		}
1215		op, ok := r.state.Accounts[req.Operator]
1216		if !ok {
1217			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1218		}
1219		granter, gOk := r.state.Accounts[a.GranterID]
1220		to, tOk := r.state.Accounts[a.ToID]
1221		if req.Operator != a.TrusteeID {
1222			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1223				ErrForbidden, req.Operator, req.AuthID)
1224		}
1225		if !gOk {
1226			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1227		}
1228		if !tOk {
1229			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1230		}
1231		if !op.Active {
1232			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1233		}
1234		if !granter.Active {
1235			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1236		}
1237		if !to.Active {
1238			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1239		}
1240		switch authzCurrentStatus(a, now) {
1241		case AuthRevoked:
1242			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1243		case AuthExpired:
1244			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1245		case AuthUsed:
1246			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1247		}
1248		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1249		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1250		h, ok := r.state.Holdings[a.ItemID]
1251		if !ok {
1252			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1253		}
1254		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1255			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1256				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1257		}
1258		return nil
1259	}
1260	
1261	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1262		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1263			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1264				ErrRequestConflict, prev.Operator, prev.RequestID)
1265		}
1266		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1267			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1268		if prev.Rejected {
1269			res.Err = codeErr(prev.Reason)
1270			return res, res.Err
1271		}
1272		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1273		// 原价款与应付明细，不重复计入。
1274		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1275		return res, nil
1276	}
