13	
14	// authzWorld 建立 alice（持有人/创作者）、bob（受托人）、carol（接收人）
15	// 三个可用账户，并向 alice 发行藏品 i1（持有版本 1）。
16	func authzWorld(t *testing.T, r *Registry) {
17		t.Helper()
18		setupWorld(t, r)
19		if err := r.RegisterAccount("carol", "接收人"); err != nil {
20			t.Fatal(err)
21		}
22		if _, err := r.Issue(issueReq("i1", "alice")); err != nil {
23			t.Fatal(err)
24		}
25	}
26	
27	func createAuthReq(r *Registry, authID string, expiry time.Duration) CreateAuthorizationRequest {
28		return CreateAuthorizationRequest{
29			Operator: "alice", Reason: "委托代转", RequestID: "create-" + authID,
30			AuthID: authID, ItemID: "i1", TrusteeID: "bob", ToID: "carol",
31			ExpectedOwner: "alice", ExpectedVer: 1,
